cy.irAMisPortfolios();
        cy.abrirPortfolio('Portfolio CYPRESS');
        cy.filtrarFechaPosicionValuada('09/02/2026');
        cy.mostrarPPC();
        cy.validarTablaPortfolios();
        cy.abrirMonedas();
        cy.obtenerSaldoMoneda('ARS').then((saldoAntes) => {
          cy.irAMisOperaciones();
          cy.filtrarFecha("02/02/2026");
          cy.clickearBotonEditar('Compra', 'Cheque', 'Cheque - Cheque aut N° 1', '52.000,00');
          cy.contains('.modal-title', 'Compra') // Busca el modal que contenga ese texto
          .should('be.visible');
          // El cheque ya existía (Costo 50.000 / Monto 52.000). Si cargamos el Costo primero, con el
          // Monto viejo (52.000) la TNA se da vuelta a negativa y al cargar el nuevo Monto (85.000) la
          // app recalcula el Costo a 130.769,23 (TNA -456%). Cargando el Monto a cobrar PRIMERO y el
          // Costo ÚLTIMO, el Costo queda en 80.000 y la TNA se deriva positiva (~81%): Interés 5.000.
          cy.ingresarMontoACobrar('85000');
          cy.ingresarCosto('80000');
          cy.aceptarOperacion();
          cy.irAMisOperaciones();
          cy.filtrarFecha("09/02/2026");
          cy.validacionGrillaOperaciones();
          cy.validarFilaOperacion('Compra', 'Cheque - Cheque aut N° 1', '85000');
          //Validación de la operación CHeque.
          cy.irAMisPortfolios();
          cy.abrirPortfolio('Portfolio CYPRESS');
          cy.filtrarFechaPosicionValuada('09/02/2026');
          cy.mostrarPPC();
          cy.validarTablaPortfolios();
          cy.abrirMonedas();
          // Nuevo costo más alto (80000 vs 50000 original) -- la compra pasa a costar más, el
          // saldo disponible disminuye.
          cy.validarImpactoSaldoMoneda('ARS', saldoAntes, 'disminucion');
          cy.abrirYValidarInstrumento('Cheques', 'Cheque - Cheque aut N° 1', '80.000');
        });
